const usuario = { nome: 'Ana', idade: 15, endereco: { cidade: 'São Paulo' } };

// Tirar duas propriedades de uma vez.
const { nome, idade } = usuario;
console.log(nome, idade);   // Ana 15

// Valor padrão: a ficha não tem cidade — usa o padrão.
const { cidade = 'Desconhecida' } = usuario;
console.log(cidade);        // Desconhecida

// Renomear: a variável é apelido, o valor vem de usuario.nome.
const { nome: apelido } = usuario;
console.log(apelido);       // Ana

// Aninhado: descer com os dois pontos.
const { endereco: { cidade: cidadeDoAluno } } = usuario;
console.log(cidadeDoAluno); // São Paulo

// Passo 1 e 2: destructuring na hora — com padrão para a cidade.
function apresentar(usuario) {
  const { nome, idade, cidade = 'algum lugar' } = usuario;

  // Passo 3: a frase usa as variáveis já prontas.
  return `${nome} tem ${idade} anos e mora em ${cidade}.`;
}

// Passo 4: os dois caminhos.
const ana = { nome: 'Ana', idade: 15, cidade: 'São Paulo' };
const bruno = { nome: 'Bruno', idade: 17 }; // sem cidade!

console.log(apresentar(ana));   // Ana tem 15 anos e mora em São Paulo.
console.log(apresentar(bruno)); // Bruno tem 17 anos e mora em algum lugar.
